package com.haucheng.erp.dto;
import jakarta.validation.constraints.*; import lombok.Data; import java.util.List;
@Data public class UserCreateRequest { @NotBlank(message="用户名不能为空") @Size(max=64) private String username; @NotBlank(message="姓名不能为空") @Size(max=100) private String realName; @Size(max=64) private String employeeNo; @NotBlank(message="密码不能为空") @Size(min=8,max=128,message="密码长度需为8到128位") private String password; @Size(max=32) private String phone; @Email(message="邮箱格式不正确") @Size(max=128) private String email; private Long departmentId; @NotEmpty(message="至少选择一个角色") private List<@NotNull Long> roleIds; private Boolean status = true; }
